mapper.select:
    	select  FEE_ID id,
    			FEE_NAME text
				,  BASIC_BILL||','||BASIS  object
    	from MST_FEEINFO



					  and APPLY_TYPE in (#{relationChannel}, #{relationOther})
					  and CHARGE_TYPE = #{CHARGE_TYPE_01}


					  APPLY_TYPE = #{relationProd}




					  and FEE_TYPE = #{feeTypeFloat}


					  and FEE_TYPE in (#{fee10}, #{fee11}, #{fee99})


					  and FEE_TYPE in (#{feeTypeTrust}, #{feeTypeFix}, #{feeTypeSale}, #{feeTypeOthSale}, #{feeTypeThService},#{feeTypeInvest})



				  and (FEE_ID like concat(concat('%', #{search}), '%') or FEE_NAME like concat(concat('%', #{search}), '%'))


				  and (FEE_ID IN (#{initValue}) or FEE_NAME IN (#{initValue}))


			     and NVL(BASIC_BILL,#{BILL_BASE_04}) = #{BILL_BASE_04}

select FCI.CASH_ID cashId, FCI.FEE_ID feeId, MF.FEE_TYPE feeType,
FCCR.BASIS basis, FCCR.BASE_TYPE basicBill, FFCR.FIRST_BASE_TYPE firstBaseType,
FCPR.END_TDAY_RULE calcFeeTradeRule, FCPR.PAY_TDAY_RULE payFeeTradeRule, FCPR.PAY_CYCLE payFeeRule, FFCR.F_ACCR_DATE provisionFirstDay, FCCR.YIELD * 100 feeRate, FCCR.BASE_DATE_TYPE netAssetValueDay, FFCR.E_ACCR_DATE eAccrDate, FCPR.FIRST_PAY_DATE firstCalEndDate, MF.CHARGE_TYPE chargeType, PLP.PROD_STYLE prodStyle from FIN_CASH_INFO FCI, MST_FEEINFO MF, FIN_CASH_PAY_RULE FCPR, FIN_CASH_CALC_RULE FCCR, FIN_FLOAT_COUNTING_RULE FFCR, FIN_PRODUCT FP left join prd_layer_param PLP on FP.FINPROD_ID = PLP.FINPROD_ID WHERE FCI.FEE_ID = MF.FEE_ID and FCI.FINPROD_ID = FP.FINPROD_ID and FCI.CASH_ID = FCCR.CASH_ID and (FCCR.EFF_DATE = FP.VDATE OR FP.FINPROD_TYPE2=#{finprodType2}) and FCI.CASH_ID = FCPR.CASH_ID and (FCPR.EFF_DATE = FP.VDATE OR FP.FINPROD_TYPE2=#{finprodType2}) and FCI.CASH_ID = FFCR.CASH_ID and (FFCR.EFF_DATE = FP.VDATE OR FP.FINPROD_TYPE2=#{finprodType2}) and (FCI.FINPROD_ID = #{finprodId} or PLP.P_FINPROD_ID = #{finprodId}) and FCI.CASH_TYPE_1 = #{cashType1} and MF.FEE_TYPE in (#{feeTypeTrust}, #{feeTypeFix}, #{feeTypeSale}, #{feeTypeOthSale}, #{feeTypeThService},#{feeTypeInvest}) and FCI.FINPROD_TYPE = #{finprodType}

select  
	from FIN_CASH_PLAN
	where FIN_CASH_PLAN.CASH_ID = (select CASH_ID from FIN_CASH_INFO
									where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
									    and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
									    and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
									    and FIN_CASH_INFO.FEE_ID = #{feeId}

									    	and FIN_CASH_INFO.BRANCH = #{branch}
									    )
	order by FIN_CASH_PLAN.MDATE ASC

	select  FEE_ID id,
			FEE_NAME text
	from MST_FEEINFO
	where APPLY_TYPE = #{relationProd}

	  		and FEE_TYPE = #{feeType}


